def CCE_BarrierOp : CCE_Op<"barrier"> {
  let summary = "Pipeline barrier synchronization";
  let description = [{
    Enforces a synchronization barrier on the specified pipeline stage,
    ensuring all prior operations on that pipeline have completed before proceeding.
    The pipe operand selects the pipeline stage (0=vvall, 1=vstvld, 2=vldvst).
  }];
  let arguments = (ins CCE_PipeAttr:$pipe);
  let results = (outs);
  let assemblyFormat = "`pipe` `=` $pipe attr-dict";
}

def CCE_CmpOp : CCE_Op<"cmp", [Pure]> {
  let summary = "Vector-vector comparison";
  let description = [{
    Compares corresponding elements of two vectors using the specified predicate string
    (e.g. "eq", "ne", "lt", "gt", "le", "ge"). A mask vector controls which lanes participate.
    The result is a vector with comparison outcomes per lane.
  }];

  let arguments = (ins VectorTypeConstraint:$lhs, VectorTypeConstraint:$rhs,
      VectorTypeConstraint:$mask, StrAttr:$predicate);

  let results = (outs CCE_PredVecType:$result);

  let assemblyFormat = "`(` $lhs `,` $rhs `,` $mask `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_CmpSOp : CCE_Op<"cmps"> {
  let summary = "Vector-scalar comparison";
  let description = [{
    Compares each element in a source vector against a scalar value using the specified
    predicate string (e.g. "eq", "ne", "lt", "gt", "le", "ge"). The dtype attribute
    specifies the element type. Results are stored in UB memory with configurable strides.
  }];

  let arguments = (ins VectorTypeConstraint:$lhs, CCE_ScalarType:$rhs,
      VectorTypeConstraint:$mask, StrAttr:$predicate);

  let results = (outs CCE_PredVecType:$result);

  let assemblyFormat = "`(` $lhs `,` $rhs `,` $mask `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_CreateCbufMatrixOp : CCE_Op<"create.cbuf.matrix"> {
  let summary =
      "Fill an L1 matrix tile with a scalar (user-facing, uses memref)";
  let description = [{
    Fills the destination L1 tile with the scalar value using the Cube
    L1-fill instruction. The dtype variant of the target intrinsic is
    determined by the destination memref element type, matching the
    MovOutToL1MultiNd2nz convention. config packing follows the hardware
    repeat format:
      [14:0]  repeat    : repeat count (32B blocks)
      [30:16] blockLen  : blocks written per repeat
      [46:32] repeatGap : block gap between consecutive repeats
    A contiguous whole-tile fill is encoded as blockLen = totalBytes/32,
    repeat = 1, repeatGap = 0.
  }];
  let arguments = (ins Arg<AnyMemRef, "L1 destination memref", [MemWrite]>:$dst,
      I64:$config, AnyType:$value);
  let results = (outs);
  let assemblyFormat = "`(`$dst `,` $config `,` $value`)` attr-dict `:` "
                       "`(`type($dst)`,` type($config)`,` type($value)`)`";
  let hasVerifier = 1;
}

def CCE_FixL0cToL1Op : CCE_Op<"fix.l0c.to.l1"> {
  let summary = "Move data from L0C to L1";
  let description = [{
    Moves data from L0C buffer to L1 buffer with fixpipe conversion.
    cfg0 packing (from __builtin_cce_copy_matrix_cc_to_cbuf):
      ((sid & 0xf) << 0) |
      ((n_size & 0xfff) << 4) |
      ((m_size & 0xffff) << 16) |
      ((loop_dst_stride & 0xffffffff) << 32)
    cfg1 packing:
      ((loop_src_stride & 0xffff) << 0) |
      ((l2_cache_ctl & 0xf) << 16) |
      ((quant_pre & 0x20) << 24) |
      ((clip_relu_pre & 0x3) << 30) |
      ((unit_flag_ctl & 0x3) << 32) |
      ((quant_pre & 0x1f) << 34) |
      ((relu_pre & 0x7) << 39) |
      ((split_en & 0x1) << 42) |
      ((NZ2ND_en & 0x1) << 43) |
      ((quant_post & 0x1f) << 44) |
      ((relu_post & 0x7) << 49) |
      ((clip_relu_post & 0x1) << 52) |
      ((loop_enhance_en & 0x1) << 53) |
      ((eltwise_op & 0x7) << 54) |
      ((eltwise_antq_en & 0x1) << 57) |
      ((loop_enhance_merge_en & 0x1) << 58) |
      ((C0_pad_en & 0x1) << 59) |
      ((wino_post_en & 0x1) << 60) |
      ((broadcast_en & 0x1) << 61) |
      ((NZ2DN_en & 0x1) << 62)
  }];
  let arguments = (ins Arg<AnyMemRef, "L1 destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "L0C source memref", [MemRead]>:$src, I64:$cfg0,
      I64:$cfg1);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $src `,` $cfg0 `,` $cfg1`)` attr-dict `:` `(`type($dst)`,` "
      "type($src)`,` type($cfg0)`,` type($cfg1)`)`";
  let hasVerifier = 1;
}

def CCE_FixL0cToOutOp : CCE_Op<"fix.l0c.to.out"> {
  let summary = "Move data from L0C to GM";
  let description = [{
    Moves data from L0C buffer to GM memory with fixpipe conversion.
    cfg0 packing (from __builtin_cce_copy_matrix_cc_to_gm):
      ((sid & 0xf) << 0) |
      ((n_size & 0xfff) << 4) |
      ((m_size & 0xffff) << 16) |
      ((loop_dst_stride & 0xffffffff) << 32)
    cfg1 packing:
      ((loop_src_stride & 0xffff) << 0) |
      ((l2_cache_ctl & 0xf) << 16) |
      ((quant_pre & 0x20) << 24) |
      ((clip_relu_pre & 0x3) << 30) |
      ((unit_flag_ctl & 0x3) << 32) |
      ((quant_pre & 0x1f) << 34) |
      ((relu_pre & 0x7) << 39) |
      ((split_en & 0x1) << 42) |
      ((NZ2ND_en & 0x1) << 43) |
      ((quant_post & 0x1f) << 44) |
      ((relu_post & 0x7) << 49) |
      ((clip_relu_post & 0x1) << 52) |
      ((loop_enhance_en & 0x1) << 53) |
      ((eltwise_op & 0x7) << 54) |
      ((eltwise_antq_en & 0x1) << 57) |
      ((loop_enhance_merge_en & 0x1) << 58) |
      ((C0_pad_en & 0x1) << 59) |
      ((wino_post_en & 0x1) << 60) |
      ((broadcast_en & 0x1) << 61) |
      ((NZ2DN_en & 0x1) << 62)
  }];
  let arguments = (ins Arg<AnyMemRef, "GM destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "L0C source memref", [MemRead]>:$src, I64:$cfg0,
      I64:$cfg1);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $src `,` $cfg0 `,` $cfg1`)` attr-dict `:` `(`type($dst)`,` "
      "type($src)`,` type($cfg0)`,` type($cfg1)`)`";
  let hasVerifier = 1;
}

def CCE_GetCtrlOp : CCE_Op<"get.ctrl"> {
  let summary = "Get control register value";
  let description = [{
    Returns the value of the CCE control register.
  }];
  let arguments = (ins);
  let results = (outs I64:$output);
  let assemblyFormat = "`->` type($output) attr-dict";
}

def CCE_GetVms4SrOp : CCE_Op<"get.vms4.sr"> {
  let summary = "Get merge-sort execution counts";
  let description = [{
    Reads VMS4_SR after vmrgsort4. The raw i64 packs the number of consumed
    proposals from source lists 0 through 3 in bits [15:0], [31:16],
    [47:32], and [63:48], respectively. Keeping the hardware query as one i64
    matches the CANN intrinsic ABI; callers may extract the four i16 fields.
  }];
  let arguments = (ins);
  let results = (outs I64:$output);
  let assemblyFormat = "`->` type($output) attr-dict";
}

