def CCE_HistV2Op : CCE_Op<"histv2", [Pure]> {
  let summary = "Frequency or cumulative histogram over u8 lanes";
  let description = [{
    Accumulates either a frequency histogram (`kind = frequency`) or a
    cumulative histogram (`kind = cumulative`). The selector is a semantic CCE
    attribute; lowering chooses the corresponding DAV-3510 intrinsic.
  }];
  let arguments = (ins CCE_AnyIntVecElemVecType:$acc,
      CCE_AnyIntVecElemVecType:$source, CCE_PredVecType:$mask, I32:$bin,
      CCE_HistogramKind:$kind);
  let results = (outs CCE_AnyIntVecElemVecType:$result);
  let assemblyFormat = "`(` $acc `,` $source `,` $mask `,` $bin `)` attr-dict "
                       "`:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_InitAlignOp : CCE_Op<"init_align"> {
  let summary = "Initialize DAV-3510 unaligned-store state";
  let description = [{
    Creates the zero/empty alignment state required at the start of a
    stateful unaligned-store stream. The state is represented explicitly as
    vector<32xi8> and must be threaded through cce.pstu, cce.vstus, or
    cce.vstur before a final cce.vstar/cce.vstas flush.
  }];
  let arguments = (ins);
  let results = (outs CCE_AlignVecType:$align);
  let assemblyFormat = "attr-dict `:` type($align)";
}

def CCE_LibdeviceOp : CCE_Op<"libdevice"> {
  let summary = "External libdevice function call (SIMD/memref path)";
  let description = [{
    SIMD path: memref in, no result (DPS style). Lowered by
    --cce-to-library-call to a private outlined wrapper. The call site keeps
    the operands as statically shaped, identity-layout memrefs. The
    type-specific wrapper builds fixed libdevice memref_t descriptors in local
    stack storage and calls the exact external function selected by the
    compiler-owned allowlist.

    Example:
      cce.libdevice "cos" (%dst, %src)
        : (memref<128xf32, #cce.address_space<ub>>, memref<128xf32, #cce.address_space<ub>>) -> ()
        -> func.call @__cce_libdevice_cos_fp32_wrapper(
             %src, %dst)
           : (memref<128xf32, #cce.address_space<ub>>, memref<128xf32, #cce.address_space<ub>>) -> ()

    For SIMT/scalar path, see cce.simt.libdevice in CCESIMTOps.td.
  }];
  let arguments = (ins Variadic<AnyType>:$inputs, StrAttr:$symbol);
  let results = (outs);
  let assemblyFormat = "$symbol `(` $inputs `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_LoadL1ToL03Dv2Op : CCE_Op<"load.l1.to.l0.3dv2"> {
  let summary = "Load an im2col window from L1 to L0A or L0B (3Dv2)";
  let description = [{
    Loads a three-dimensional sliding window from L1 into a Cube input
    buffer.  The scalar operands deliberately preserve the public AscendC
    `img2colv2_cbuf_to_ca/cb` contract; the backend `.cfg` intrinsic performs
    the target-specific packing.

    `stepK`, `stepM`, `posK`, `posM`, and `channelSize` have uint16 semantics;
    `strideW`, `strideH`, `kernelW`, `kernelH`, `dilationW`, and `dilationH`
    have uint8 semantics; the remaining four operands are boolean controls.
    All are represented as i64 SSA values to match the captured DAV-3510
    LLVM intrinsic ABI without lossy casts.
  }];
  let arguments =
      (ins Arg<AnyMemRef, "L0A or L0B destination memref", [MemWrite]>:$dst,
          Arg<AnyMemRef, "L1 source memref", [MemRead]>:$src, I64:$stepK,
          I64:$stepM, I64:$posK, I64:$posM, I64:$strideW, I64:$strideH,
          I64:$kernelW, I64:$kernelH, I64:$dilationW, I64:$dilationH,
          I64:$filterW, I64:$filterH, I64:$transpose, I64:$fmatrixCtrl,
          I64:$channelSize);
  let results = (outs);
  let assemblyFormat = "operands attr-dict `:` type(operands)";
  let hasVerifier = 1;
}

def CCE_LoadL1ToL0Mx2Dv2Op : CCE_Op<"load.l1.to.l0.mx.2dv2"> {
  let summary = "Load MX scale data from L1 to L0A or L0B";
  let description = [{
    Loads an 8-bit MX scale matrix. The destination address space selects the
    L0A or L0B backend intrinsic. The intrinsic ABI receives the destination as
    an i64 address, the L1 source pointer, and two packed configuration words.
  }];
  let arguments =
      (ins Arg<AnyMemRef, "L0A or L0B destination memref", [MemWrite]>:$dst,
          Arg<AnyMemRef, "L1 source memref", [MemRead]>:$src, I64:$cfg0,
          I64:$cfg1);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $src `,` $cfg0 `,` $cfg1`)` attr-dict `:` `(`type($dst)`,` "
      "type($src)`,` type($cfg0)`,` type($cfg1)`)`";
  let hasVerifier = 1;
}

def CCE_LoadL1ToL0A2Dv2Op : CCE_Op<"load.l1.to.l0a.2dv2"> {
  let summary = "Load from L1 to L0A with 2Dv2 format";
  let description = [{
    Loads data from L1 local memory to L0A buffer in 2Dv2 format.
    The dtype is derived from the memref element type during lowering.
    cfg0 packing (from __builtin_cce_load_cbuf_to_ca):
      ((mStartPosition & 0xffff) << 0) |
      ((kStartPosition & 0xffff) << 16) |
      ((mStep & 0xff) << 32) |
      ((kStep & 0xff) << 40)
    cfg1 packing:
      ((srcStride & 0xffff) << 0) |
      ((dstStride & 0xffff) << 16)
    cfg2: transpose enable flag (1 = 转置/transpose, 0 = 不转置/no transpose)
  }];
  let arguments =
      (ins Arg<AnyMemRef, "L0A destination memref", [MemWrite]>:$dst,
          Arg<AnyMemRef, "L1 source memref", [MemRead]>:$src, I64:$cfg0,
          I64:$cfg1, I64:$cfg2);
  let results = (outs);
  let assemblyFormat = "`(`$dst `,` $src `,` $cfg0 `,` $cfg1 `,` $cfg2`)` "
                       "attr-dict `:` `(`type($dst)`,` type($src)`,` "
                       "type($cfg0)`,` type($cfg1)`,` type($cfg2)`)`";
  let hasVerifier = 1;
}

