def CCE_MadOp : CCE_Op<"mad"> {
  let summary = "Cube c310 MAD op (user-facing, uses memref)";
  let description = [{
    Performs matrix multiply-accumulate: L0C += L0A * L0B.
    The dtype variant is determined by the source memref element types during
    lowering. Equal f32, f16, and bf16 source pairs accumulate to f32. The
    builtin FP8 E4M3FN/E5M2 source combinations also accumulate to f32.
    config packing formula (from __builtin_cce_mad):
      ((m & 0xfff) << 0) |
      ((k & 0xfff) << 12) |
      ((n & 0xfff) << 24) |
      ((unit_Flag_ctrl & 0x3) << 55) |
      ((gemv_ctrl & 0x1) << 61) |
      ((BTbuf_ctrl & 0x1) << 62) |
      ((zero_Cmatrix_ctrl & 0x1) << 63)
  }];
  let arguments =
      (ins Arg<AnyMemRef, "L0C destination memref", [MemWrite]>:$dst,
          Arg<AnyMemRef, "L0A source memref", [MemRead]>:$srcA,
          Arg<AnyMemRef, "L0B source memref", [MemRead]>:$srcB, I64:$config);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $srcA `,` $srcB `,` $config`)` attr-dict `:` "
      "`(`type($dst)`,` type($srcA)`,` type($srcB)`,` type($config)`)`";
  let hasVerifier = 1;
}

def CCE_MadMxOp : CCE_Op<"mad.mx"> {
  let summary = "DAV-3510 MX matrix multiply";
  let description = [{
    Executes native MMAD.MX. Source element types select builtin FP8 pairs
    or matching E2M1/E1M2 packed FP4 pairs. FP4 payloads remain byte-sized
    L0A/L0B pairs; their E8M0 scale tiles are loaded separately and
    associated with those data addresses before this operation. dst is FP32 in
    L0C and config is the packed XT control word.
  }];
  let arguments = (ins Arg<AnyMemRef, "L0C f32 destination", [MemWrite]>:$dst,
      Arg<AnyMemRef, "L0A MX source", [MemRead]>:$srcA,
      Arg<AnyMemRef, "L0B MX source", [MemRead]>:$srcB, I64:$config);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $srcA `,` $srcB `,` $config`)` attr-dict `:` "
      "`(`type($dst)`,` type($srcA)`,` type($srcB)`,` type($config)`)`";
  let hasVerifier = 1;
}

