def CCE_MovOutToL1AlignV2DvOp : CCE_Op<"mov.out.to.l1.align.v2.dv"> {
  let summary = "Move data from GM to L1 with ALIGN.V2.DV";
  let description = [{
    Direct DAV-3510 GM-to-L1 DMA. The element type selects the intrinsic
    suffix; cfg0 and cfg1 are the two packed hardware control words.
  }];
  let arguments = (ins Arg<AnyMemRef, "L1 destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "GM source memref", [MemRead]>:$src, I64:$cfg0, I64:$cfg1);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $src `,` $cfg0 `,` $cfg1`)` attr-dict `:` `(`type($dst)`,` "
      "type($src)`,` type($cfg0)`,` type($cfg1)`)`";
  let hasVerifier = 1;
}

def CCE_MovOutToL1MultiNd2nzOp : CCE_Op<"mov.out.to.l1.multi.nd2nz"> {
  let summary =
      "Move data from GM to L1 with ND2NZ format (user-facing, uses memref)";
  let description = [{
    Moves data from GM (global memory) to L1 buffer in ND2NZ format.
    Supports f32, f16, bf16, f8E4M3FN, f8E5M2, and i8 byte carriers for packed
    payloads such as E2M1 and E8M0. The dtype variant is determined by the
    matching source and destination memref element type.
    config0 packing (from __builtin_cce_copy_gm_to_cbuf_multi_nd2nz):
      ((sid & 0xf) << 0) |
      ((loop1_src_stride & 0xffffffffff) << 4) |
      ((l2_cache_ctrl_mode & 0xf) << 44) |
      ((n_value & 0xffff) << 48)
    config1 packing:
      ((d_value & 0x1fffff) << 0) |
      ((loop4_src_stride & 0xffffffffff) << 21) |
      ((smallc0_en & 0x1) << 61)
  }];
  let arguments = (ins Arg<AnyMemRef, "L1 destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "GM source memref", [MemRead]>:$src, I64:$config0,
      I64:$config1);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst `,` $src `,` $config0 `,` $config1`)` attr-dict `:` "
      "`(`type($dst)`,` type($src)`,` type($config0)`,` type($config1)`)`";
  let hasVerifier = 1;
}

def CCE_MovOutToUbAlignV2DvMemrefOp : CCE_Op<"mov.out.to.ub.align.v2.dv"> {
  let summary = "Move data from GM to UB with V2.DV alignment (memref)";
  let description = [{
    Moves data from GM memory to UB buffer with V2.DV alignment.
    cfg1 packing (from __builtin_cce_copy_gm_to_ubuf_align_v2):
      ((sid & 0xf) << 0) |
      ((burst_num & 0x1fffff) << 4) |
      ((burst_len & 0x1fffff) << 25) |
      ((left_padding_count & 0x3f) << 46) |
      ((right_padding_count & 0x3f) << 52) |
      ((data_select_bit & 0x1) << 58) |
      ((l2_cache_ctl & 0xf) << 60)
    cfg2 packing:
      ((burst_src_stride & 0xffffffffff) << 0) |
      ((burst_dst_stride & 0x1fffff) << 40)
  }];
  let arguments = (ins Arg<AnyMemRef, "UB destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "GM source memref", [MemRead]>:$src, I64:$cfg1, I64:$cfg2);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst`,` $src`,` $cfg1`,` $cfg2`)` attr-dict `:` `(`type($dst)`,` "
      "type($src)`,` type($cfg1)`,` type($cfg2)`)`";
  let hasVerifier = 0;
}

def CCE_MovUbToL1V310Op : CCE_Op<"mov.ub.to.l1.v310"> {
  let summary =
      "Move data from UB buffer to L1 buffer (user-facing, uses memref)";
  let description = [{
    Moves data from UB local memory to L1 local memory.
    cfg packing (from __builtin_cce_copy_ubuf_to_cbuf):
      ((sub_blockid & 0x1) << 0) |
      ((burst_num & 0xfff) << 4) |
      ((burst_len & 0xffff) << 16) |
      ((src_gap & 0xffff) << 32) |
      ((dst_gap & 0xffff) << 48)
  }];
  let arguments = (ins Arg<AnyMemRef, "L1 destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "UB source memref", [MemRead]>:$src, I64:$cfg);
  let results = (outs);
  let assemblyFormat = "`(`$dst `,` $src `,` $cfg`)` attr-dict `:` "
                       "`(`type($dst)`,` type($src)`,` type($cfg)`)`";
}

