    immediate or register-backed; backend translation selects the final IMM or
    REG intrinsic form.
  }];
  let arguments = (ins CCE_PipeAttr:$pipe, CCE_PipeAttr:$tpipe,
      OptionalAttr<CCE_EventAttr>:$static_event_id,
      Optional<I64>:$dynamic_event_id);
  let results = (outs);
  let assemblyFormat = [{
    `pipe` `=` $pipe `tpipe` `=` $tpipe
    (`pipeID` `=` $static_event_id^)?
    (`event` `=` $dynamic_event_id^ `:` type($dynamic_event_id))?
    attr-dict
  }];
  let hasVerifier = 1;
}

