def CCE_SIMTAtomicCASOp
    : CCE_Op<"simt.atomic_cas", [MemoryEffects<[MemRead, MemWrite]>]> {
  let summary = "Target-aware SIMT atomic compare-and-swap";
  let arguments = (ins AnyMemRef:$memref, Variadic<Index>:$indices,
      AnyType:$compare, AnyType:$value,
      DefaultValuedAttr<
                       CCE_SIMTAtomicCachePolicy,
                       "::mlir::cce::SIMTAtomicCachePolicy::NORMAL_FV">:$cache);
  let results = (outs AnyType:$result);
  let hasVerifier = 1;
  let assemblyFormat = [{
    $memref `[` $indices `]` `,` $compare `,` $value
    oilist(`cache` `=` $cache) attr-dict `:`
    functional-type(operands, results)
  }];
}

def CCE_SIMTAtomicRMWOp
    : CCE_Op<"simt.atomic_rmw", [MemoryEffects<[MemRead, MemWrite]>]> {
  let summary = "Target-aware SIMT atomic read-modify-write";
  let arguments = (ins AnyMemRef:$memref, Variadic<Index>:$indices,
      AnyType:$value, CCE_SIMTAtomicKind:$kind,
      DefaultValuedAttr<
                       CCE_SIMTAtomicSignedness,
                       "::mlir::cce::SIMTAtomicSignedness::SIGNED">:$signedness,
      DefaultValuedAttr<
                       CCE_SIMTAtomicCachePolicy,
                       "::mlir::cce::SIMTAtomicCachePolicy::NORMAL_FV">:$cache);
  let results = (outs AnyType:$result);
  let hasVerifier = 1;
  let assemblyFormat = [{
    $kind $memref `[` $indices `]` `,` $value
    oilist(`signedness` `=` $signedness | `cache` `=` $cache)
    attr-dict `:` functional-type(operands, results)
  }];
}

def CCE_SIMTCastOp : CCE_Op<"simt.cast", [Pure]> {
  let summary = "SIMT type conversion (scalar int<->fp, packed vector fp<->fp)";
  let description = [{
    Unified type conversion op. The translation layer selects the lowering
    path based on src/dst types:
    - Packed vector fp<->fp (e.g. vector<2xf32> <-> vector<2xbf16/f8>):
      maps to llvm.hivm.{src}x2.to.{dst}x2 intrinsics.
    - Scalar int->fp: maps to LLVM SIToFP/UIToFP (selected by `signedness`).
    - Scalar fp->int: maps to LLVM FPToSI/FPToUI (selected by `signedness`).
    `signedness` is only meaningful for int<->fp conversions; it is ignored
    for packed vector fp<->fp conversions.
  }];
  let arguments = (ins AnyTypeOf<[AnyFloat, AnySignlessInteger,
                                  CCE_AnyVecElemWithF8VecType]>:$src,
      DefaultValuedAttr<CCE_SIMTIntSignedness,
                        "::mlir::cce::SIMTIntSignedness::SIGNED">:$signedness);
  let results = (outs AnyTypeOf<[AnyFloat, AnySignlessInteger,
                                 CCE_AnyVecElemWithF8VecType]>:$result);
  let assemblyFormat = [{
    `(` $src `)` oilist(`signedness` `=` $signedness) attr-dict `:` type($src) `to` type($result)
  }];
}

