ops.excerpt:
def CCE_SIMTDcciOp : CCE_Op<"simt.dcci"> {
  let summary = "SIMT data-context cache invalidate";
  let description = [{
    Invalidates the data context cache. With the `dst_context` unit attribute
    set, maps to llvm.hivm.DCCI_DST_CONTEXT (used in pure-SIMT kernels);
    otherwise maps to llvm.hivm.DCCI (non-pure-SIMT mode).
  }];
  let arguments = (ins OptionalAttr<UnitAttr>:$dst_context);
  let results = (outs);
  let assemblyFormat = "oilist(`dst_context` $dst_context) attr-dict";
}

def CCE_SIMTFenceOp : CCE_Op<"simt.fence"> {
  let summary = "SIMT memory fence (device or block scope)";
  let description = [{
    Ensures all memory writes made by the calling thread are visible to other
    threads. `scope` selects the fence scope:
    - device: llvm.hivm.fence.workitems       (all threads in device)
    - block:  llvm.hivm.fenceblock.workitems  (threads in same block)
  }];
  let arguments = (ins CCE_SIMTFenceScope:$scope);
  let results = (outs);
  let assemblyFormat = "$scope attr-dict";
}

def CCE_SIMTFfmaOp : CCE_Op<"simt.ffma", [Pure]> {
  let summary = "SIMT fused multiply-add (f32)";
  let description = [{
    Computes a * b + c for f32 with rounding. Maps to
    llvm.hivm.ffma_f32_rrr.
  }];
  let arguments = (ins F32:$a, F32:$b, F32:$c);
  let results = (outs F32:$result);
  let assemblyFormat = "`(` $a `,` $b `,` $c `)` attr-dict `:` type($a)";
}

def CCE_SIMTLibdeviceOp : CCE_Op<"simt.libdevice"> {
  let summary = "External libdevice function call (SIMT/scalar path)";
  let description = [{
    SIMT path: scalar in, scalar result. Lowered by --cce-to-library-call
    pass to func.call without emit_c_wrapper (scalars passed directly).

    Example:
      %r = cce.simt.libdevice "cos" (%x) : (f32) -> f32
        -> func.call @_mlir_ciface_simt_cos_float(%x) : (f32) -> f32

    For SIMD/memref path, see cce.libdevice in CCEOps.td.
  }];
  let arguments = (ins Variadic<AnyType>:$inputs, StrAttr:$symbol);
  let results = (outs Variadic<AnyType>:$results);
  let assemblyFormat = "$symbol `(` $inputs `)` attr-dict `:` "
                       "functional-type($inputs, $results)";
}

def CCE_SIMTLoadOp : CCE_Op<"simt.load", [MemoryEffects<[MemRead]>,
                                          AttrSizedOperandSegments]> {
  let summary = "SIMT memory load with cache controls and optional mask";
  let description = [{
    Loads a scalar or vector from a memref with independent cache option and
    L2 cache hint attributes.
    For global memory (addr space 1), maps to
    llvm.hivm.ldg.{cache|uncache}.s{N} where N is the element bit width.
    For shared/local memory (addr space 6), lowers to plain llvm.load.
    Vectors wider than 64 bits are split into multiple <=64-bit loads.
    When `mask` is present and false, the load is skipped and 0 is returned.
  }];
  let arguments = (ins AnyMemRef:$memref, Variadic<Index>:$indices,
      Optional<I1>:$mask,
      DefaultValuedAttr<CCE_SIMTCacheOption,
                        "::mlir::cce::SIMTCacheOption::CACHE">:$cacheOption,
      DefaultValuedAttr<
                       CCE_SIMTLoadCacheHint,
                       "::mlir::cce::SIMTLoadCacheHint::NORMAL_FV">:$cacheHint);
  let results =
      (outs AnyTypeOf<[CCE_ScalarType, CCE_AnyVecElemWithF8VecType]>:$result);
  let assemblyFormat = [{
    $memref `[` $indices `]`
    oilist(`mask` `=` $mask | `cacheOption` `=` $cacheOption |
            `cacheHint` `=` $cacheHint)
    attr-dict `:` type($memref) `to` type($result)
  }];
}

def CCE_SIMTMul64hiOp : CCE_Op<"simt.mul64hi", [Pure]> {
  let summary = "SIMT high 64 bits of 64x64 multiplication";
  let description = [{
    Computes the high 64 bits of a 64x64->128 unsigned multiplication.
    Maps to llvm.hivm.mul64hi_ui.
  }];
  let arguments = (ins I64:$a, I64:$b);
  let results = (outs I64:$result);
  let assemblyFormat = "`(` $a `,` $b `)` attr-dict `:` type($a)";
}

def CCE_SIMTMulI32ToI64Op : CCE_Op<"simt.mul_i32toi64", [Pure]> {
  let summary = "SIMT 32x32->64 multiplication";
  let description = [{
    Computes the 64-bit product of two 32-bit integers. `signedness` selects
    signed (llvm.hivm.mul_i32toi64_i) or unsigned (llvm.hivm.mul_i32toi64_ui).
  }];
  let arguments = (ins I32:$a, I32:$b,
      DefaultValuedAttr<CCE_SIMTIntSignedness,
                        "::mlir::cce::SIMTIntSignedness::SIGNED">:$signedness);
  let results = (outs I64:$result);
  let assemblyFormat = [{
    `(` $a `,` $b `)` oilist(`signedness` `=` $signedness) attr-dict `:` type($a) `to` type($result)
  }];
}

def CCE_SIMTMulhiOp : CCE_Op<"simt.mulhi", [Pure]> {
  let summary = "SIMT high 32 bits of 32x32 multiplication";
  let description = [{
    Computes the high 32 bits of a 32x32->64 multiplication. `signedness`
    selects signed (llvm.hivm.mulhi_i) or unsigned (llvm.hivm.mulhi_ui).
  }];
  let arguments = (ins I32:$a, I32:$b,
      DefaultValuedAttr<CCE_SIMTIntSignedness,
                        "::mlir::cce::SIMTIntSignedness::SIGNED">:$signedness);
  let results = (outs I32:$result);
  let assemblyFormat = [{
    `(` $a `,` $b `)` oilist(`signedness` `=` $signedness) attr-dict `:` type($a)
  }];
}

def CCE_SIMTQueryPtrOp : CCE_Op<"simt.query_ptr", [Pure]> {
  let summary = "SIMT pointer address-space query";
  let description = [{
    Returns i1 true if the given pointer resides in the queried address space.
    `kind` selects the target space:
    - global: llvm.hivm.isgm   (addr space 1)
    - ubuf:  llvm.hivm.isub    (addr space 6)
    - local: llvm.hivm.islocal  (local memory)
  }];
  let arguments = (ins LLVM_AnyPointer:$ptr, CCE_SIMTPtrQueryKind:$kind);
  let results = (outs I1:$result);
  let assemblyFormat = "$kind `(` $ptr `)` attr-dict `:` type($ptr)";
}

def CCE_SIMTReduceOp : CCE_Op<"simt.reduce", [Pure]> {
  let summary = "SIMT warp-level reduction";
  let description = [{
    Performs a reduction across all lanes of a warp in one hardware instruction.
    `kind` selects add/max/min. `signedness` selects signed/unsigned for
    integer max/min (ignored for add and for float types).
    Result type selects the underlying intrinsic dtype: i32/f32/f16.
    Maps to llvm.hivm.redux.{add|max|min}.{s32|u32|f32|f16}.
  }];
  let arguments =
      (ins AnyTypeOf<[I32, F32, F16]>:$src, CCE_SIMTReduceKind:$kind,
          DefaultValuedAttr<
              CCE_SIMTReduceSignedness,
              "::mlir::cce::SIMTReduceSignedness::SIGNED">:$signedness);
  let results = (outs AnyTypeOf<[I32, F32, F16]>:$result);
  let assemblyFormat = [{
    $kind $src oilist(`signedness` `=` $signedness) attr-dict `:` type($src)
    `to` type($result)
  }];
}

def CCE_SIMTStoreOp : CCE_Op<"simt.store", [MemoryEffects<[MemWrite]>,
                                            AttrSizedOperandSegments]> {
  let summary = "SIMT memory store with cache controls and optional mask";
  let description = [{
    Stores a scalar or vector to a memref with independent cache option and
    L2 cache hint attributes.
    For global memory (addr space 1), maps to
    llvm.hivm.stg.{cache|uncache}.b{N} where N is the element bit width.
    For shared/local memory (addr space 6), lowers to plain llvm.store.
    Vectors wider than 64 bits are split into multiple <=64-bit stores.
    When `mask` is present and false, the store is skipped.
  }];
  let arguments =
      (ins AnyMemRef:$memref, Variadic<Index>:$indices,
          AnyTypeOf<[CCE_ScalarType, CCE_AnyVecElemWithF8VecType]>:$value,
          Optional<I1>:$mask,
          DefaultValuedAttr<CCE_SIMTCacheOption,
                            "::mlir::cce::SIMTCacheOption::CACHE">:$cacheOption,
          DefaultValuedAttr<
              CCE_SIMTStoreCacheHint,
              "::mlir::cce::SIMTStoreCacheHint::NORMAL_FV">:$cacheHint);
  let results = (outs);
  let assemblyFormat = [{
    $value `,` $memref `[` $indices `]`
    oilist(`mask` `=` $mask | `cacheOption` `=` $cacheOption |
            `cacheHint` `=` $cacheHint)
    attr-dict `:` type($memref) `,` type($value)
  }];
}

def CCE_SIMTStoreVFSIMTInfoOp : CCE_Op<"simt.store_vfsimt_info"> {
  let summary = "Store VF SIMT config information";
  let arguments = (ins I64:$config);
  let results = (outs);
  let assemblyFormat = "`(` $config `)` attr-dict `:` type($config)";
}

def CCE_SIMTSyncThreadsOp : CCE_Op<"simt.sync_threads"> {
  let summary = "Synchronize SIMT work items";
  let arguments = (ins);
  let results = (outs);
  let assemblyFormat = "attr-dict";
}

def CCE_SIMTVoteOp : CCE_Op<"simt.vote", [Pure]> {
  let summary = "SIMT warp-level vote";
  let description = [{
    Performs a per-lane boolean reduction across the warp. `kind` selects
    all/any/uni/ballot. For all/any/uni the result is i1; for ballot the
    result is i32 (one bit per lane). Maps to llvm.hivm.vote.{all|any|uni|
    ballot}.
  }];
  let arguments = (ins I1:$pred, CCE_SIMTVoteKind:$kind);
  let results = (outs AnyTypeOf<[I1, I32]>:$result);
  let assemblyFormat = [{
    $kind $pred attr-dict `:` type($pred) `to` type($result)
  }];
}

def CCE_SIMTScopeOp : CCE_Op<"simt_scope", [IsolatedFromAbove]> {
  let summary = "Structured SIMT execution scope";
  let description = [{
    Marks scalar code that is outlined into a SIMT entry function. `captures`
    are passed to the outlined function and must correspond one-to-one with
    the entry block arguments.

    `threads` is the physical thread shape `[x, y, z]`. `work_items` records
    the logical iteration count represented by the scope, while
    `work_per_thread` records how many logical items one thread handles. These
    two values are scheduling information; bounds checks remain explicit in
    the region so non-divisible iteration spaces preserve source semantics.

    `vf_config` is the hardware launch configuration consumed by
    llvm.hivm.store.vfsimt.info. Keeping it explicit avoids baking a
    target-specific encoding into the CCE semantic layer.

    Ordinary scalar computation and control flow inside the region should use
    arith, math, memref and scf. CCE SIMT operations are reserved for hardware
    execution state and synchronization that community dialects cannot express.
  }];
  let arguments = (ins Variadic<AnyType>:$captures, DenseI64ArrayAttr:$threads,
      I64Attr:$work_items, DefaultValuedAttr<I64Attr, "1">:$work_per_thread,
      I64Attr:$vf_config);
  let regions = (region AnyRegion:$body);
  let assemblyFormat = [{
    `(` $captures `)` `(` $body `)` attr-dict `:`
    functional-type($captures, results)
  }];
  let hasVerifier = 1;
}

def CCE_SprClrOp : CCE_Op<"sprclr"> {
  let summary = "Clear an A5 special-purpose register";
  let description = [{
    Clears the alignment special-purpose register before beginning a stateful
    operation sequence. DAV-3510 currently exposes no other public choice; the
    operation lowers to the backend's i16 immediate 74.
  }];
  let arguments = (ins);
  let results = (outs);
  let assemblyFormat = "attr-dict";
}

def CCE_VAbsDifOp : CCE_Op<"vabsdif", [Pure]> {
  let summary = "Vector absolute difference (f32/f16/i32/i16/i8)";
  let description = [{
    Computes the absolute difference between corresponding elements of two vectors
    with predicate masking: dst[i] = |src0[i] - src1[i]| for active lanes.
    Supports f32, f16, i32, i16, and i8 element types.
  }];
  let arguments = (ins CCE_AnyVecElemVecType:$src0, CCE_AnyVecElemVecType:$src1,
      CCE_PredVecType:$preg);
  let results = (outs CCE_AnyVecElemVecType:$dst);
  let assemblyFormat = "`(` $src0 `,` $src1 `,` $preg `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VAddOp : BinaryVector<"vadd"> {
  let summary = "Vector addition";
  let description = [{
    Performs element-wise addition of two vectors with masking support.
    Floating-point operations are strict unless an optional `fastmath`
    attribute of type `arith::FastMathFlagsAttr` permits relaxation. In
    particular, `contract` on both a multiply and its add consumer permits
    their replacement by a single-rounding multiply-add instruction.
  }];
}

def CCE_VAddS : VecScalarOp<"vadds"> {
  let summary = "Vector-scalar add";
  let description = [{
    CCE_VAddS: result = src + scalar
  }];
}

def CCE_VAndOp : BinaryVector<"vand"> {
  let summary = "Vector bitwise AND";
  let description = [{
    Performs element-wise bitwise AND of two vectors with masking support.
  }];
}

def CCE_VAxpyOp : CCE_Op<"vaxpy", [Pure]> {
  let summary = "Vector AXPY";
  let description = [{
    Computes old_dst + src * scalar. The old destination is an explicit SSA
    operand because the hardware intrinsic reads and writes that register.
    The directly supported DAV-3510 register forms are f16 and f32 with
    merging mask semantics.
  }];
  let arguments = (ins CCE_FloatVecElemVecType:$old_dst,
      CCE_FloatVecElemVecType:$src, CCE_ScalarType:$scalar,
      CCE_PredVecType:$mask);
  let results = (outs CCE_FloatVecElemVecType:$result);
  let assemblyFormat = "`(` $old_dst `,` $src `,` $scalar `,` $mask `)` "
                       "attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VBitSortOp : CCE_Op<"vbitsort"> {
  let summary = "Sort 32 score/index pairs in UB";
  let description = [{
    Sorts f16/f32 scores together with their i32 indices and writes packed
    records to a UB destination. config is the hardware control word; the
    public repeat count is encoded as (repeat & 0xff) << 56.
  }];
  let arguments = (ins Arg<AnyMemRef, "UB destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "UB score source memref", [MemRead]>:$src,
      Arg<AnyMemRef, "UB i32 index source memref", [MemRead]>:$indices,
      I64:$config);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst`,` $src`,` $indices`,` $config`)` attr-dict `:` "
      "`(`type($dst)`,` type($src)`,` type($indices)`,` type($config)`)`";
  let hasVerifier = 1;
}

def CCE_VBrOp : CCE_Op<"vbr", [Pure]> {
  let summary = "Vector broadcast";
  let description = [{
    Broadcasts a scalar immediate value across all active vector lanes.
    Produces a vector where each lane is filled with the same scalar value.
  }];
  let arguments = (ins AnyType:$imm);
  let results = (outs AnyType:$res);
  let assemblyFormat =
      "`(`$imm`)` attr-dict `:` `(`type($imm)`)` `->` type($res)";
}

def CCE_VCaddOp : ReductionOp<"vcadd"> {
  let summary = "Vector addition reduction";
  let description = [{
    Add all active elements together and write the result to the lowest element
    of the destination vector register. Other element positions are filled with all 0s.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCbmaxOp : ReductionCbOp<"vcbmax"> {
  let summary = "Vector maximum reduction with predicate output";
  let description = [{
    Find the maximum element in the source vector and write the result to the
    lowest element of the destination vector register, and generate predication
    for each matching maximum element locations.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCbminOp : ReductionCbOp<"vcbmin"> {
  let summary = "Vector minimum reduction with predicate output";
  let description = [{
    Find the minimum element in the source vector and write the result to the
    lowest element of the destination vector register, and generate predication
    for each matching minimum element locations.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCgaddOp : ReductionOp<"vcgadd"> {
  let summary = "Vector addition group reduction";
  let description = [{
    Add all active elements in each 32B block together and write the result
    continuously to the LSBs of the destination vector register.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCgmaxOp : ReductionOp<"vcgmax"> {
  let summary = "Vector maximum group reduction";
  let description = [{
    Find all active elements in each 32B block of the source vector and write
    the result continuously to the LSBs of the destination vector register.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCgminOp : ReductionOp<"vcgmin"> {
  let summary = "Vector minimum group reduction";
  let description = [{
    Find the minimum element in each block of the source vector and write the
    result continuously to the LSBs of the destination vector register.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

def CCE_VCIOp : CCE_Op<"vci", [Pure]> {
  let summary = "Vector constant increment with direction control (no mask)";
  let description = [{
    Generates a sequence vector: when seq_mode = 0, lane i holds
    start + i (ascending); when seq_mode = 1, lane i holds
    start + (vec_len - 1 - i) (descending).
    E.g. start=0, seq_mode=0 → [0, 1, 2, ..., 63]
         start=0, seq_mode=1 → [63, 62, 61, ..., 0]
    Supports f32, f16, i32, i16 element types. No predicate mask — all lanes
    are active. The first argument determines the output vector element type.
    The second argument is always i32 (0 = ascending, 1 = descending).
  }];
  let arguments = (ins AnyTypeOf<[I32, I16, F32, F16]>:$start, I32:$seq_mode);
  let results = (outs CCE_AnyVecElemVecType:$dst);
  let assemblyFormat = "`(` $start `,` $seq_mode `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VCmaxOp : ReductionOp<"vcmax"> {
  let summary = "Vector maximum reduction";
  let description = [{
    Find the maximum element in the source vector and write the result to the
    lowest element of the destination vector register.
    A mask is provided to tell which elements are involved in the src vector.
  }];
}

