    follows the existing BF16-to-F16 operation: src, mask, sat, round. The
    saturation operand is ignored for F16-to-BF16 because that intrinsic does
    not accept it.
  }];
  let arguments = (ins VectorTypeConstraint:$src, VectorTypeConstraint:$mask,
      I32:$sat, I32:$round);
  let results = (outs VectorTypeConstraint:$result);
  let assemblyFormat = "`(` $src `,` $mask `,` $sat `,` $round `)` attr-dict "
                       "`:` functional-type(operands, results)";
}

