  let summary = "Vector-scalar minimum";
  let description = [{
    CCE_VMinSOp: result = min(src, scalar)
  }];
}

def CCE_VModOp : BinaryVector<"vmod"> {
  let summary = "Vector modulo";
  let description = [{
    Performs element-wise modulo of two integer vectors with masking support.
    dst[i] = lhs[i] mod rhs[i].
    Supports i8, i16, and i32 element types (signed and unsigned variants).
  }];
}

def CCE_VMrgSort4Op : CCE_Op<"vmrgsort4"> {
  let summary = "Merge four sorted UB streams";
  let description = [{
    Merges four pre-sorted f16/f32 streams. The CCE-level op keeps the four UB
    memrefs explicit. CCE-to-intrinsic lowering packs their addresses into the
    hardware source-address operand as four 16-bit fields containing
    (address >> 3) & 0xffff.
  }];
  let arguments = (ins Arg<AnyMemRef, "UB destination memref", [MemWrite]>:$dst,
      Arg<AnyMemRef, "first UB source", [MemRead]>:$src0,
      Arg<AnyMemRef, "second UB source", [MemRead]>:$src1,
      Arg<AnyMemRef, "third UB source", [MemRead]>:$src2,
      Arg<AnyMemRef, "fourth UB source", [MemRead]>:$src3, I64:$count,
      I64:$config);
  let results = (outs);
  let assemblyFormat =
      "`(`$dst`,` $src0`,` $src1`,` $src2`,` $src3`,` $count`,` $config`)` "
      "attr-dict `:` `(`type($dst)`,` type($src0)`,` type($src1)`,` "
      "type($src2)`,` type($src3)`,` type($count)`,` type($config)`)`";
  let hasVerifier = 1;
}

def CCE_VMulOp : BinaryVector<"vmul"> {
  let summary = "Vector multiplication";
  let description = [{
    Performs element-wise multiplication of two vectors with masking support.
    Like `cce.vadd`, an optional `arith::FastMathFlagsAttr` named `fastmath`
    may explicitly permit floating-point contraction. Missing permission
    preserves the separate multiply rounding.
  }];
}

def CCE_VMulaOp : CCE_Op<"vmula", [Pure]> {
  let summary = "Vector fused multiply add";
  let arguments = (ins VectorTypeConstraint:$acc, VectorTypeConstraint:$lhs,
      VectorTypeConstraint:$rhs, VectorTypeConstraint:$mask);
  let results = (outs VectorTypeConstraint:$result);
  let assemblyFormat = "`(` $acc `,` $lhs `,` $rhs `,` $mask `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_VMullOp : BinaryVectorMull<"vmull"> {
  let summary = "Vector multiply long";
  let description = [{
    Performs element-wise multiply-long of two vectors with masking support.
    Produces two result vectors (for the full double-width product).
    An optional pass_thru vector can be specified for merging.
  }];
}

def CCE_VMulS : VecScalarOp<"vmuls"> {
  let summary = "Vector-scalar multiply";
  let description = [{
    CCE_VMulS: result = src * scalar
  }];
}

def CCE_VMulsCvtOp : CCE_Op<"vmulscvt", [Pure]> {
  let summary = "Fused f32 vector-scalar multiply and f16 conversion";
  let description = [{
    Multiplies a vector<64xf32> by an f32 scalar and converts the selected
    half to vector<128xf16>. The part operand selects the low/even or
    high/odd half according to the hardware Part encoding.
  }];
  let arguments = (ins CCE_FloatVecElemVecType:$src, F32:$scalar,
      CCE_PredVecType:$mask, I32:$part);
  let results = (outs CCE_FloatVecElemVecType:$result);
  let assemblyFormat = "`(` $src `,` $scalar `,` $mask `,` $part `)` attr-dict "
                       "`:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VOrOp : BinaryVector<"vor"> {
  let summary = "Vector bitwise OR";
  let description = [{
    Performs element-wise bitwise OR of two vectors with masking support.
  }];
}

def CCE_VpackOp : CCE_Op<"vpack", [Pure]> {
  let summary = "Vector pack elements";
  let description = [{
    Packs vector elements according to the part parameter.
    The part i32 selects which portion of the vector to pack.
    Supports f32/f16/bf16/i32/i16/i8 vector element types.
  }];
  let arguments = (ins CCE_AnyVecElemVecType:$src, I32:$part);
  let results = (outs CCE_AnyVecElemVecType:$res);
  let assemblyFormat =
      "`(` $src `,` $part `)` attr-dict `:` functional-type(operands, results)";
}

def CCE_VPreluOp : BinaryVector<"vprelu"> {
  let summary = "Vector PReLU activation";
  let description = [{
    Performs element-wise PReLU (Parametric ReLU) activation.
    Supports f16 and f32 element types.
  }];
}

def CCE_VSAddOp : BinaryVector<"vsadd"> {
  let summary = "Saturated vector addition";
  let description = [{
    Performs element-wise saturated addition of two i16 vectors with masking support.
  }];
}

def CCE_VScatterOp : CCE_Op<"vscatter"> {
  let summary = "Vector scatter store to memory";
  let description = [{
    Stores vector elements to non-contiguous memory locations using index vectors.
    Each index in the indices vector specifies an offset from the base address.
    A predicate mask controls which elements are stored.
  }];
  let arguments = (ins CCE_AnyVecElemWithF8VecType:$data, LLVM_AnyPointer:$base,
      CCE_AnyVecElemWithF8VecType:$indices, CCE_PredVecType:$preg);
  let results = (outs);
  let assemblyFormat = "`(` $data `,` $base `,` $indices `,` $preg `)` "
                       "attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VSelOp : CCE_Op<"vsel", [Pure]> {
  let summary = "Vector conditional select";
  let description = [{
    Selects elements from src0 or src1 based on a predicate mask.
    For each lane, if preg[i] is 1, dst[i] = src0[i]; otherwise dst[i] = src1[i].
    Supports f32/f16/bf16/i32/i16/i8/f8e4m3fn/f8e5m2 element types.
  }];
  let arguments = (ins CCE_AnyVecElemWithF8VecType:$src0,
      CCE_AnyVecElemWithF8VecType:$src1, CCE_PredVecType:$preg);
  let results = (outs CCE_AnyVecElemWithF8VecType:$dst);
  let assemblyFormat = "`(` $src0 `,` $src1 `,` $preg `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VselrOp : CCE_Op<"vselr", [Pure]> {
  let summary = "Vector select reduce";
  let description = [{
    Selects elements for reduce using an index vector.
    Supports B8/B16/B32 data and index widths.
  }];
  let arguments = (ins CCE_AnyVecElemVecType:$src,
      CCE_AnyVecElemVecType:$index);
  let results = (outs CCE_AnyVecElemVecType:$dst);
  let assemblyFormat = "`(` $src `,` $index `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_VShlOp : BinaryVectorShiftByVector<"vshl"> {
  let summary = "Vector shift left";
  let description = [{
    Shifts elements of a vector left by a scalar value with masking support.
  }];
}

def CCE_VShlsOp : BinaryVectorShift<"vshls"> {
  let summary = "Vector shift right with shifting";
  let description = [{
    Shifts elements of a vector right with shifting by a scalar value with masking support.
  }];
}

def CCE_VShrOp : BinaryVectorShiftByVector<"vshr"> {
  let summary = "Vector shift right";
  let description = [{
    Shifts elements of a vector right by a scalar value with masking support.
  }];
}

def CCE_VShrsOp : BinaryVectorShift<"vshrs"> {
  let summary = "Vector shift right with saturation";
  let description = [{
    Shifts elements of a vector right with saturation by a scalar value with masking support.
  }];
}

def CCE_VSldbOp : CCE_Op<"vsldb"> {
  let summary = "Vector strided load from memory";
  let description = [{
    Loads a vector from a UB buffer with a packed stride configuration, using
    a predicate mask. This is the non-post-update DAV-3510 form and lowers to
    a dtype-specific cce.intr.vsldb.* pointer op. The distinct post-update
    hardware form also returns an updated base and is not modeled by this op.
    DAV-3510 distribution loads support B8, B16, and B32 element widths.
  }];
  let arguments = (ins Arg<AnyMemRef, "UB source memref", [MemRead]>:$src,
      I32:$strideConfig, CCE_PredVecType:$mask);
  let results = (outs CCE_AnyVecElemVecType:$data);
  let assemblyFormat = "`(`$src`,` $strideConfig`,` $mask`)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VSlideOp : CCE_Op<"vslide", [Pure]> {
  let summary = "Vector slide by offset (no bf16 support)";
  let description = [{
    Shifts vector elements by a constant offset, with zero-fill for vacated lanes.
    Supports f32/f16/i32/i16/i8 element types (no bf16).
  }];
  let arguments = (ins CCE_SlideVecElemVecType:$src0,
      CCE_SlideVecElemVecType:$src1, I16:$offset);
  let results = (outs CCE_SlideVecElemVecType:$dst);
  let assemblyFormat = "`(` $src0 `,` $src1 `,` $offset `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VSqzOp : CCE_Op<"vsqz", [Pure]> {
  let summary = "Compress predicate-selected vector lanes";
  let description = [{
    Compacts active lanes toward the front. store_hint must be zero unless
    the result directly feeds the matching unaligned store path; setting it
    without that consumer can deadlock the vector queues.
  }];
  let arguments = (ins CCE_AnyVecElemVecType:$src, CCE_PredVecType:$mask,
      I32:$store_hint);
  let results = (outs CCE_AnyVecElemVecType:$result);
  let assemblyFormat = "`(` $src `,` $mask `,` $store_hint `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VSstbOp : CCE_Op<"vsstb"> {
  let summary = "Vector strided store to memory";
  let description = [{
    Stores a vector to UB buffer with a stride configuration
    and post-update enable flag, using a predicate mask.
    This is the user-facing variant that uses memref types.
    It will be lowered to cce.intr.vsstb.* during the CCE-to-CCEIntr conversion pass.
    Does not support i64 element type.
  }];
  let arguments = (ins CCE_AnyVecElemWithF8VecType:$data,
      Arg<AnyMemRef, "UB destination memref", [MemWrite]>:$dst,
      I32:$strideConfig, I32:$postUpdateEnable, CCE_PredVecType:$mask);
  let results = (outs);
  let assemblyFormat =
      "`(`$data`,` $dst`,` $strideConfig`,` $postUpdateEnable`,` $mask`)` "
      "attr-dict `:` `(`type($data)`,` type($dst)`,` type($strideConfig)`,` "
      "type($postUpdateEnable)`,` type($mask)`)`";
  let hasVerifier = 1;
}

def CCE_VSSubOp : BinaryVector<"vssub"> {
  let summary = "Saturated vector subtraction";
  let description = [{
    Performs element-wise saturated subtraction of two i16 vectors with masking support.
  }];
}

def CCE_VStOp : CCE_Op<"vst"> {
  let summary = "Vector store to memory";
  let description = [{
    Stores a vector to memory at address (base + offset) using a predicate mask.
    The data vector element type and lane count determine the transfer width.
    Supports f32/f16/bf16/i32/i16/i8/f8e4m3fn/f8e5m2/i64 element types.
  }];
  let arguments = (ins CCE_MemVecElemVecType:$data, LLVM_AnyPointer:$base,
      I32:$offset, CCE_PredVecType:$preg);
  let results = (outs);
  let assemblyFormat = "`(` $data `,` $base `,` $offset `,` $preg `)` "
                       "attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VStarOp : CCE_Op<"vstar"> {
  let summary = "Finalize an unaligned vector store";
  let description = [{
    Flushes the DAV-3510 unaligned-store alignment state to UB. The state is
    represented by vector<32xi8>; CCE-to-intrinsic lowering appends the ABI's
    reserved zero operand.
  }];
  let arguments = (ins CCE_AlignVecType:$value,
      Arg<AnyMemRef, "UB destination", [MemWrite]>:$dst);
  let results = (outs);
  let assemblyFormat =
      "`(` $value `,` $dst `)` attr-dict `:` `(`type($value)`,` type($dst)`)`";
  let hasVerifier = 1;
}

def CCE_VStasOp : CCE_Op<"vstas"> {
  let summary = "Store unaligned-vector alignment state to UB";
  let description = [{
    Stores vector<32xi8> alignment state to UB. byteOffset is the hardware byte
    offset from the memref base; CCE-to-intrinsic lowering appends the ABI's
    reserved zero operand.
  }];
  let arguments = (ins CCE_AlignVecType:$value,
      Arg<AnyMemRef, "UB destination", [MemWrite]>:$dst, I32:$byteOffset);
  let results = (outs);
  let assemblyFormat = "`(` $value `,` $dst `,` $byteOffset `)` attr-dict `:` "
                       "functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VStsX1Op : CCE_Op<"vstsx1"> {
  let summary = "Vector store stride x1 (user-facing, memref)";
  let description = [{
    Stores a vector to UB buffer with stride and distance parameters.
    This is the user-facing variant that uses memref types.
    It will be lowered to cce.intr.vstsx1.f16/f32/i8/i16/i32 during the
    CCE-to-CCEIntr conversion pass. FP8 vectors use the bit-preserving i8
    carrier intrinsic. An i64 buffer may use a vector<64xi32> bit carrier for
    operations, such as select, that have no native b64 vector instruction.
    The norm parameter specifies the data distribution mode.
  }];
  let arguments = (ins CCE_AnyVecElemWithF8VecType:$src,
      Arg<AnyMemRef, "UB destination memref", [MemWrite]>:$dst, I32:$stride,
      I32:$norm, I32:$postupdate, CCE_PredVecType:$preg);
  let results = (outs);
  let assemblyFormat =
      "`(`$src`,` $dst`,` $stride`,` $norm`,` $postupdate`,` $preg`)` "
      "attr-dict `:` `(`type($src)`,` type($dst)`,` type($stride)`,` "
      "type($norm)`,` type($postupdate)`,` type($preg)`)`";
  let hasVerifier = 1;
}

def CCE_VsturOp : CCE_Op<"vstur"> {
  let summary = "Stateful unaligned residual vector store";
  let description = [{
    Updates an unaligned-store stream from a residual vector. The
    postUpdateEnable operand is the CCE integer form of PTO's
    NO_POST_UPDATE/POST_UPDATE mode and must be a constant 0 or 1. The backend
    ABI appends one reserved zero operand.
  }];
  let arguments = (ins CCE_AlignVecType:$align, CCE_MemVecElemVecType:$value,
      Arg<AnyMemRef, "unaligned UB destination", [MemWrite]>:$dst,
      I32:$postUpdateEnable);
  let results = (outs CCE_AlignVecType:$updatedAlign);
  let assemblyFormat = "`(` $align `,` $value `,` $dst `,` $postUpdateEnable "
                       "`)` attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VstusOp : CCE_Op<"vstus"> {
  let summary = "Stateful unaligned vector store with scalar element count";
  let description = [{
    Stores a scalar-selected prefix of one physical vector to UB and returns
    the updated buffered-tail state. elementOffset is expressed in destination
    elements; lowering converts it to the byte operand required by
    llvm.hivm.vstus. The stream must be terminated by cce.vstar or cce.vstas.
    Byte-per-i1 UB destinations use an i8 vector carrier, as with vstsx1.
  }];
  let arguments = (ins CCE_AlignVecType:$align, I32:$elementOffset,
      CCE_MemVecElemVecType:$value,
      Arg<AnyMemRef, "unaligned UB destination", [MemWrite]>:$dst);
  let results = (outs CCE_AlignVecType:$updatedAlign);
  let assemblyFormat = "`(` $align `,` $elementOffset `,` $value `,` $dst `)` "
                       "attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VSubOp : BinaryVector<"vsub"> {
  let summary = "Vector subtraction";
  let description = [{
    Performs element-wise subtraction of two vectors with masking support.
  }];
}

def CCE_VtrcOp : CCE_Op<"vtrc", [Pure]> {
  let summary = "Vector truncate/round";
  let description = [{
    Vector truncate/round operation.
    Supports f32 (64 lanes), f16 (128 lanes), bf16 (128 lanes).
  }];
  let arguments = (ins VectorTypeConstraint:$src, I32:$param,
      VectorTypeConstraint:$mask);
  let results = (outs VectorTypeConstraint:$result);
  let assemblyFormat = "`(` $src `,` $param `,` $mask `)` attr-dict `:` "
                       "functional-type(operands, results)";
}

def CCE_VUnpackOp : CCE_Op<"vunpack", [Pure]> {
  let summary = "Widen one half of an integer vector";
  let description = [{
    Widens i8 to i16 or i16 to i32. The optional unsigned attribute selects
    zero extension; without it the operation sign-extends. part must be 0 or
    1. DAV-3510's i32-to-i64 public API is a composed sequence, not this
    direct intrinsic.
  }];
  let arguments = (ins CCE_AnyIntVecElemVecType:$src, I32:$part,
      OptionalAttr<UnitAttr>:$is_unsigned);
  let results = (outs CCE_AnyIntVecElemVecType:$result);
  let assemblyFormat =
      "`(` $src `,` $part `)` attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VUsqzOp : CCE_Op<"vusqz", [Pure]> {
  let summary = "Materialize exclusive active-lane ranks from a predicate";
  let description = [{
    DAV-3510 VUSQZ returns, in each integer lane, the number of active
    predicate lanes preceding that lane. The src operand is the two-address
    carrier required by the private LLVM ABI; hardware does not consume its
    value. Keeping it explicit preserves the intrinsic ABI until CCE gains an
    undef/poison carrier convention.
  }];
  let arguments = (ins CCE_AnyIntVecElemVecType:$src, CCE_PredVecType:$mask);
  let results = (outs CCE_AnyIntVecElemVecType:$result);
  let assemblyFormat =
      "`(` $src `,` $mask `)` attr-dict `:` functional-type(operands, results)";
  let hasVerifier = 1;
}

def CCE_VXorOp : BinaryVector<"vxor"> {
  let summary = "Vector bitwise XOR";
  let description = [{
    Performs element-wise bitwise XOR of two vectors with masking support.
  }];
}

def CCE_WaitFlagDevPipeImmOp : CCE_Op<"wait.flag.dev.pipe.imm"> {
  let summary = "FFTS block/subblock synchronization instructions.";
  let description = [{
    '$flag_id' : Each flag ID has a counter. If the flag ID has been set by
      FFTS, the counter will be incremented. If the WAIT_FLAG_DEV of the same
      flag ID has been executed, the counter will be decremented. If the counter
      of flag ID is zero, all the instructions after this instruction will be
      blocked. It will wait until the counter is not zero.
  }];
  let arguments = (ins CCE_PipeAttr:$pipe, I64Attr:$flag_id);
  let results = (outs);
  let assemblyFormat = "`pipe` `=` $pipe `,` `flag_id` `=` $flag_id attr-dict";
}

def CCE_WaitFlagDevPipeRegOp : CCE_Op<"wait.flag.dev.pipe.reg"> {
  let summary = "FFTS block/subblock synchronization instructions.";
  let description = [{
    '$flag_id' : Each flag ID has a counter. If the flag ID has been set by
      FFTS, the counter will be incremented. If the WAIT_FLAG_DEV of the same
      flag ID has been executed, the counter will be decremented. If the counter
      of flag ID is zero, all the instructions after this instruction will be
      blocked. It will wait until the counter is not zero.
  }];
  let arguments = (ins CCE_PipeAttr:$pipe, I64:$flag_id);
  let results = (outs);
  let assemblyFormat =
      "`pipe` `=` $pipe `flag_id` `=` $flag_id attr-dict `:` type($flag_id)";
}

def CCE_WaitFlagDevRegOp : CCE_Op<"wait.flag.dev.reg"> {
  let summary = "FFTS block/subblock synchronization instructions.";
  let description = [{
    '$flag_id' : Each flag ID has a counter. If the flag ID has been set by
      FFTS, the counter will be incremented. If the WAIT_FLAG_DEV of the same
      flag ID has been executed, the counter will be decremented. If the counter
      of flag ID is zero, all the instructions after this instruction will be
      blocked. It will wait until the counter is not zero.
  }];
  let arguments = (ins I64:$flag_id);
  let results = (outs);
  let assemblyFormat = "`(` $flag_id `)` attr-dict `:` type($flag_id)";
}

def CCE_WaitIntraBlockiModeOp : CCE_Op<"wait.intra.blocki.mode"> {
  let summary = "Wait intra-blocki mode";
  let description = [{
    Waits until the intra-blocki mode is enabled data exchange between pipeline stages.
    Then pipe operand specifies the source pipeline, and syncid identifies the target pipeline.
  }];
  let arguments = (ins CCE_PipeAttr:$pipe, I64:$syncid);
  let results = (outs);
  let assemblyFormat = "`pipe` `=` $pipe `syncid` `=` $syncid attr-dict";
}

