  let summary = "Internal print op with llvm.ptr input (post-lowering)";
  let description = [{
    Internal debug print operation used after the CCEPrintLowering pass.
    Accepts LLVM pointer (GM/UB only) or scalar input. Shape and element type
    are passed as explicit attributes since LLVM pointers do not carry type info.

    Function name pattern:
    - pointer: _mlir_ciface_print_{rank}d_{dtype}_{mem}
    - scalar:  _mlir_ciface_print_scalar_{dtype}_gm

    where mem is "gm" (address space 1) or "ubuf" (address space 6).
  }];
  let arguments = (ins StrAttr:$prefix,
      AnyTypeOf<[CCE_PrintPointerSrc, AnyInteger, AnyFloat,
                 CCE_AnyVecElemWithF8VecType]>:$src,
      OptionalAttr<ArrayAttr>:$shape, OptionalAttr<TypeAttr>:$elementType,
      OptionalAttr<I32Attr>:$memSpace, UnitAttr:$hex);
  let results = (outs);
  let assemblyFormat = "$prefix $src attr-dict `:` type($src)";
  let hasVerifier = 1;
}

