def CCE_IntrSIMTAtomicRMWOp
    : CCE_IntrOp<"intr.simt.atomic_rmw", [MemoryEffects<[MemRead, MemWrite]>]> {
  let summary = "SIMT atomic read-modify-write (intrinsic, LLVM pointer)";
  let description = [{
    Atomic read-modify-write on a global-memory LLVM pointer. Maps to
    llvm.hivm.atom.{KIND}.{G|S}.{dtype}. The kind/signedness/cache are
    preserved as attributes from the user-facing cce.simt.atomic_rmw.
  }];
  let arguments = (ins LLVM_PointerGM:$ptr,
      AnyTypeOf<[CCE_ScalarType, CCE_AnyVecElemWithF8VecType]>:$value,
      CCE_SIMTAtomicKind:$kind,
      DefaultValuedAttr<
                       CCE_SIMTAtomicSignedness,
                       "::mlir::cce::SIMTAtomicSignedness::SIGNED">:$signedness,
      DefaultValuedAttr<
                       CCE_SIMTAtomicCachePolicy,
                       "::mlir::cce::SIMTAtomicCachePolicy::NORMAL_FV">:$cache);
  let results =
      (outs AnyTypeOf<[CCE_ScalarType, CCE_AnyVecElemWithF8VecType]>:$result);
  let assemblyFormat = [{
    $kind $ptr `,` $value
    oilist(`signedness` `=` $signedness | `cache` `=` $cache)
    attr-dict `:` type($ptr) `,` type($value) `to` type($result)
  }];
}

