      DefaultValuedAttr<CCE_SIMTCacheOption,
                        "::mlir::cce::SIMTCacheOption::CACHE">:$cacheOption,
      DefaultValuedAttr<
                       CCE_SIMTLoadCacheHint,
                       "::mlir::cce::SIMTLoadCacheHint::NORMAL_FV">:$cacheHint);
  let results =
      (outs AnyTypeOf<[CCE_ScalarType, CCE_AnyVecElemWithF8VecType]>:$result);
  let assemblyFormat = [{
    $ptr oilist(`cacheOption` `=` $cacheOption | `cacheHint` `=` $cacheHint)
    attr-dict `:` type($ptr) `to` type($result)
  }];
}

